import "server-only";
import sgMail from "@sendgrid/mail";

if (!process.env.SENDGRID_API_KEY) {
  throw new Error("SENDGRID_API_KEY is missing from .env.local");
}
if (!process.env.SENDGRID_FROM_EMAIL) {
  throw new Error("SENDGRID_FROM_EMAIL is missing from .env.local");
}

// @sendgrid/mail stores the API key in module-level state.
sgMail.setApiKey(process.env.SENDGRID_API_KEY);

export { sgMail };
export const SENDGRID_FROM_EMAIL = process.env.SENDGRID_FROM_EMAIL;

