"use server";

import { sgMail, SENDGRID_FROM_EMAIL } from "./client";

export interface SendEmailParams {
  to: string | string[];
  subject: string;
  /** HTML body — used when not sending via a Dynamic Template */
  html: string;
  text?: string;
  replyTo?: string;
}

export interface SendTemplateParams {
  to: string | string[];
  /** ID of a SendGrid Dynamic Transactional Template.
   * Find it in SendGrid dashboard → Email API → Dynamic Templates. */
  templateId: string;
  dynamicTemplateData: Record<string, unknown>;
  replyTo?: string;
}

export interface SendResult {
  success: boolean;
  messageId?: string;
  error?: Error;
}

/** Send a transactional email with a raw HTML body. */
export async function sendEmail(params: SendEmailParams): Promise<SendResult> {
  try {
    const [response] = await sgMail.send({
      from: SENDGRID_FROM_EMAIL,
      to: params.to,
      subject: params.subject,
      html: params.html,
      text: params.text,
      replyTo: params.replyTo,
    });
    return {
      success: true,
      messageId: response.headers["x-message-id"] as string | undefined,
    };
  } catch (err: unknown) {
    return { success: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}

/**
 * Send a transactional email using a SendGrid Dynamic Template.
 * Dynamic Templates are managed in the SendGrid dashboard and referenced by ID —
 * use this for production email designs with personalisation tokens.
 */
export async function sendWithTemplate(
  params: SendTemplateParams,
): Promise<SendResult> {
  try {
    const [response] = await sgMail.send({
      from: SENDGRID_FROM_EMAIL,
      to: params.to,
      templateId: params.templateId,
      dynamicTemplateData: params.dynamicTemplateData,
      replyTo: params.replyTo,
    });
    return {
      success: true,
      messageId: response.headers["x-message-id"] as string | undefined,
    };
  } catch (err: unknown) {
    return { success: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}

