import crypto from "crypto";

export interface SendGridEvent {
  event:
    | "processed"
    | "dropped"
    | "delivered"
    | "deferred"
    | "bounce"
    | "open"
    | "click"
    | "unsubscribe"
    | "group_unsubscribe"
    | "group_resubscribe"
    | "spamreport";
  email: string;
  timestamp: number;
  sg_message_id?: string;
  /** Bounce/drop reason */
  reason?: string;
  /** URL for click events */
  url?: string;
  [key: string]: unknown;
}

/**
 * Verifies a SendGrid signed Event Webhook.
 *
 * SendGrid signs webhooks with ECDSA P-256 (prime256v1) using SHA-256.
 * The signature is in raw IEEE P1363 format (64-byte r‖s), NOT DER-encoded —
 * `dsaEncoding: "ieee-p1363"` is required or verification will always fail.
 *
 * This is the first ECDSA-based component in this registry. All other
 * webhook components use HMAC (Stripe, Calendly, Sanity) or verbatim
 * comparison (Strapi, Contentful).
 *
 * @param payload   - Raw request body string
 * @param signature - Value of `x-twilio-email-event-webhook-signature` header (base64)
 * @param timestamp - Value of `x-twilio-email-event-webhook-timestamp` header
 * @param publicKey - PEM public key from SendGrid Event Webhooks settings
 */
export function verifyWebhookSignature(
  payload: string,
  signature: string,
  timestamp: string,
  publicKey: string,
): boolean {
  try {
    const data = Buffer.from(timestamp + payload);
    const sig = Buffer.from(signature, "base64");
    return crypto.verify(
      "sha256",
      data,
      { key: publicKey, format: "pem", dsaEncoding: "ieee-p1363" },
      sig,
    );
  } catch {
    // Malformed key or signature — treat as invalid.
    return false;
  }
}

/**
 * Handles a batch of SendGrid Event Webhook events.
 *
 * SendGrid delivers multiple events per HTTP request — this function
 * receives the parsed array. Add your own DB or notification logic
 * inside each case block.
 */
export async function handleSendGridEvents(
  events: SendGridEvent[],
): Promise<void> {
  for (const event of events) {
    switch (event.event) {
      case "bounce":
      case "dropped": {
        console.log(
          `[sendgrid] Undeliverable: ${event.email} — ${event.reason ?? event.event}`,
        );
        // TODO: Mark the address as undeliverable in your database to
        // avoid sending to it again (required for CAN-SPAM compliance).
        break;
      }
      case "unsubscribe":
      case "group_unsubscribe":
      case "spamreport": {
        console.log(`[sendgrid] Suppression: ${event.email} — ${event.event}`);
        // TODO: Update your suppression list. Continuing to send to
        // unsubscribed/spam-reporting addresses violates CAN-SPAM / GDPR.
        break;
      }
      case "delivered": {
        console.log(
          `[sendgrid] Delivered: ${event.sg_message_id ?? "(no message id)"}`,
        );
        break;
      }
      default:
        console.log(`[sendgrid] Event: ${event.event} for ${event.email}`);
    }
  }
}

