import { headers } from "next/headers";
import {
  handleSendGridEvents,
  verifyWebhookSignature,
} from "@/infra/sendgrid/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("x-twilio-email-event-webhook-signature");
  const timestamp = headersList.get("x-twilio-email-event-webhook-timestamp");

  if (!signature || !timestamp) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.SENDGRID_WEBHOOK_PUBLIC_KEY) {
    console.error("[sendgrid webhook] SENDGRID_WEBHOOK_PUBLIC_KEY is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (
    !verifyWebhookSignature(
      body,
      signature,
      timestamp,
      process.env.SENDGRID_WEBHOOK_PUBLIC_KEY,
    )
  ) {
    console.error("[sendgrid webhook] Invalid ECDSA signature");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  // SendGrid delivers events as a JSON array, not a single object.
  let events;
  try {
    events = JSON.parse(body);
    if (!Array.isArray(events)) {
      throw new Error("Expected an array of events");
    }
  } catch (err: unknown) {
    console.error("[sendgrid webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so SendGrid retries — distinct from 4xx above.
  try {
    await handleSendGridEvents(events);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[sendgrid webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
